import type { PlacementDrive } from './placement-drive-model';
import type { Student } from './student-model';

export const DriveApplicationStatusKeyToLabel = {
  'StatusKey0': 'Applied',
  'StatusKey1': 'Shortlisted',
  'StatusKey2': 'Interview Scheduled',
  'StatusKey3': 'Selected',
  'StatusKey4': 'Rejected',
  'StatusKey5': 'Withdrawn'
} as const;
export type DriveApplicationStatusKey = keyof typeof DriveApplicationStatusKeyToLabel;

export interface DriveApplication {
  /**
   * @displayName Drive Application ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Application Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  applicationName: string;
  /**
   * @displayName Applied At
   * @validationRule Required for create/update operations
   */
  appliedAt: string;
  /**
   * @displayName Placement Drive
   * @validationRule Required for create/update operations
   */
  placementDrive: Pick<PlacementDrive, 'id' | 'companyName'>;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: DriveApplicationStatusKey;
  /**
   * @displayName Student
   * @validationRule Required for create/update operations
   */
  student: Pick<Student, 'id' | 'name1'>;
}

export const _DriveApplication = 'DriveApplication' as const;
